    "ACCOUNT_ID", "PROFILE_MONTH",
    "MSCI_ESG_RATING", "INDUSTRY_CLASSIFICATION",
    "ESG_SCORE_OVERALL", "ENVIRONMENTAL_SCORE", "SOCIAL_SCORE", "GOVERNANCE_SCORE",
